('pc-org-dhafra-tech-2', 'org-dhafra-tech', 'Al Dhafra Technical Institute (synthetic)', 'معهد الظفرة التقني (افتراضي)', 'university', 'rdr-2025-1', 'radiation_chemistry', 'course_change', 'Radiation protection technician module', 'وحدة فني الوقاية من الإشعاع', 'The existing chemistry technician programme adds a radiation protection module with dosimetry practice and contamination control.', 'يضيف برنامج فني الكيمياء الحالي وحدة في الوقاية من الإشعاع تشمل تطبيقات قياس الجرعات ومكافحة التلوث.', array['sk-rp-01']::text[], 2, '[{"term":"2026S1","seats":18},{"term":"2026S2","seats":18},{"term":"2027S1","seats":18}]'::jsonb, '[{"term":"2026S1","enrolled":11,"completed":0,"note":null,"reported_by":"org-dhafra-tech:admin","reported_at":"2026-09-30T09:00:00Z"}]'::jsonb, 'active', null, 'pending', null, null, null, 1, '[{"action":"create","version":1,"at":"2026-03-02T09:00:00Z","by":"org-dhafra-tech:admin","plan":[{"term":"2026S1","seats":18},{"term":"2026S2","seats":18},{"term":"2027S1","seats":18}]}]'::jsonb, 'org-dhafra-tech:admin', '2026-03-02T09:00:00Z', 'org-dhafra-tech:admin', '2026-09-30T09:00:00Z', false, true),
('pc-org-ruwais-vti-1', 'org-ruwais-vti', 'Ruwais Vocational Training Institute (synthetic)', 'معهد الرويس للتدريب المهني (افتراضي)', 'university', 'rdr-2025-1', 'maintenance', 'apprenticeship', 'Mechanical maintenance apprenticeship', 'تلمذة مهنية في الصيانة الميكانيكية', 'An employer-linked apprenticeship in rotating equipment, pumps and valves, assessed against the plant maintenance skills.', 'تلمذة مهنية مرتبطة بأصحاب العمل في المعدات الدوارة والمضخات والصمامات، تُقيَّم وفق مهارات الصيانة في المحطة.', array['sk-mp-01']::text[], 2, '[{"term":"2025S2","seats":16},{"term":"2026S1","seats":16},{"term":"2026S2","seats":20}]'::jsonb, '[{"term":"2025S2","enrolled":9,"completed":7,"note":null,"reported_by":"org-ruwais-vti:admin","reported_at":"2026-08-12T09:00:00Z"},{"term":"2026S1","enrolled":15,"completed":0,"note":null,"reported_by":"org-ruwais-vti:admin","reported_at":"2026-09-29T09:00:00Z"}]'::jsonb, 'active', null, 'queried', 'The first term filled 9 of 16 places. Please share the recruitment plan for the next intake.', 'p-chco', '2026-08-20T09:00:00Z', 1, '[{"action":"create","version":1,"at":"2026-02-20T09:00:00Z","by":"org-ruwais-vti:admin","plan":[{"term":"2025S2","seats":16},{"term":"2026S1","seats":16},{"term":"2026S2","seats":20}]}]'::jsonb, 'org-ruwais-vti:admin', '2026-02-20T09:00:00Z', 'org-ruwais-vti:admin', '2026-09-29T09:00:00Z', false, true),
('pc-org-ruwais-vti-2', 'org-ruwais-vti', 'Ruwais Vocational Training Institute (synthetic)', 'معهد الرويس للتدريب المهني (افتراضي)', 'university', 'rdr-2025-1', 'emergency', 'new_course', 'First-responder short course for industrial sites', 'دورة قصيرة للمستجيبين الأوائل في المواقع الصناعية', 'A new short course on emergency response roles, muster and communication for workers across the region''s industrial sites.', 'دورة قصيرة جديدة حول أدوار الاستجابة للطوارئ والتجمع والتواصل للعاملين في المواقع الصناعية بالمنطقة.', array['sk-ep-01']::text[], 1, '[{"term":"2026S2","seats":40},{"term":"2027S1","seats":40}]'::jsonb, '[]'::jsonb, 'active', null, 'pending', null, null, null, 1, '[{"action":"create","version":1,"at":"2026-06-15T09:00:00Z","by":"org-ruwais-vti:admin","plan":[{"term":"2026S2","seats":40},{"term":"2027S1","seats":40}]}]'::jsonb, 'org-ruwais-vti:admin', '2026-06-15T09:00:00Z', 'org-ruwais-vti:admin', '2026-06-15T09:00:00Z', false, true),
('pc-ku-1', 'ku', 'Khalifa University (incl. ENTC)', 'جامعة خليفة (بما في ذلك مركز الإمارات للتكنولوجيا النووية)', 'university', 'rdr-2025-1', 'digital', 'course_change', 'Graduate elective: digital instrumentation and plant data', 'مقرر اختياري للدراسات العليا: الأجهزة الرقمية وبيانات المحطة', 'A graduate elective on digital instrumentation and control, plant data quality and the validation of data-driven tools.', 'مقرر اختياري للدراسات العليا في الأجهزة والتحكم الرقمي وجودة بيانات المحطة والتحقق من الأدوات المعتمدة على البيانات.', array['sk-da-01']::text[], 3, '[{"term":"2026S1","seats":20},{"term":"2026S2","seats":20}]'::jsonb, '[{"term":"2026S1","enrolled":19,"completed":0,"note":null,"reported_by":"p-k-university","reported_at":"2026-09-25T09:00:00Z"}]'::jsonb, 'active', null, 'acknowledged', null, 'p-chco', '2026-03-25T09:00:00Z', 1, '[{"action":"create","version":1,"at":"2026-03-15T09:00:00Z","by":"p-k-university","plan":[{"term":"2026S1","seats":20},{"term":"2026S2","seats":20}]}]'::jsonb, 'p-k-university', '2026-03-15T09:00:00Z', 'p-k-university', '2026-09-25T09:00:00Z', false, true),
('pc-ku-2', 'ku', 'Khalifa University (incl. ENTC)', 'جامعة خليفة (بما في ذلك مركز الإمارات للتكنولوجيا النووية)', 'university', 'rdr-2025-1', 'human_performance', 'new_course', 'Human performance and safety culture module', 'وحدة الأداء البشري وثقافة السلامة', 'A module for engineering undergraduates on human performance tools, error traps and safety culture in high-reliability industries.', 'وحدة لطلاب البكالوريوس في الهندسة حول أدوات الأداء البشري ومصائد الأخطاء وثقافة السلامة في الصناعات عالية الموثوقية.', array['sk-hu-01']::text[], 2, '[{"term":"2026S2","seats":60},{"term":"2027S2","seats":60}]'::jsonb, '[]'::jsonb, 'active', null, 'acknowledged', null, 'p-chco', '2026-05-20T09:00:00Z', 1, '[{"action":"create","version":1,"at":"2026-05-10T09:00:00Z","by":"p-k-university","plan":[{"term":"2026S2","seats":60},{"term":"2027S2","seats":60}]}]'::jsonb, 'p-k-university', '2026-05-10T09:00:00Z', 'p-k-university', '2026-05-10T09:00:00Z', false, true),
('pc-ku-3', 'ku', 'Khalifa University (incl. ENTC)', 'جامعة خليفة (بما في ذلك مركز الإمارات للتكنولوجيا النووية)', 'university', 'rdr-2025-1', 'plant_systems', 'cohort', 'Reactor plant systems spring school', 'المدرسة الربيعية لأنظمة محطات المفاعلات', 'An intensive spring school on primary and secondary plant systems for final-year engineering students.', 'مدرسة ربيعية مكثفة حول أنظمة المحطة الأولية والثانوية لطلاب السنة النهائية في الهندسة.', array['sk-pf-01','sk-pf-02','sk-pf-03']::text[], 2, '[{"term":"2025S2","seats":30}]'::jsonb, '[{"term":"2025S2","enrolled":30,"completed":28,"note":null,"reported_by":"p-k-university","reported_at":"2026-07-10T09:00:00Z"}]'::jsonb, 'active', null, 'acknowledged', null, 'p-chco', '2026-02-12T09:00:00Z', 1, '[{"action":"create","version":1,"at":"2026-02-05T09:00:00Z","by":"p-k-university","plan":[{"term":"2025S2","seats":30}]}]'::jsonb, 'p-k-university', '2026-02-05T09:00:00Z', 'p-k-university', '2026-07-10T09:00:00Z', false, true),
('pc-org-alnoor-1', 'org-alnoor', 'Al Noor Precision Engineering LLC (synthetic)', 'النور للهندسة الدقيقة (اصطناعية)', 'supplier', 'rdr-2025-1', 'maintenance', 'apprenticeship', 'Precision machining apprenticeship for nuclear-grade parts', 'تلمذة مهنية في التشغيل الدقيق للقطع النووية', 'Apprentices learn precision machining, measurement and documentation to the quality standard required for nuclear-grade parts.', 'يتعلم المتدربون التشغيل الدقيق والقياس والتوثيق وفق معيار الجودة المطلوب للقطع ذات الدرجة النووية.', array['sk-mp-01']::text[], 2, '[{"term":"2025S2","seats":12},{"term":"2026S1","seats":12},{"term":"2026S2","seats":12}]'::jsonb, '[{"term":"2025S2","enrolled":12,"completed":11,"note":null,"reported_by":"p-alnoor-gm","reported_at":"2026-08-03T09:00:00Z"},{"term":"2026S1","enrolled":12,"completed":0,"note":null,"reported_by":"p-alnoor-gm","reported_at":"2026-09-22T09:00:00Z"}]'::jsonb, 'active', null, 'acknowledged', null, 'p-chco', '2026-03-04T09:00:00Z', 1, '[{"action":"create","version":1,"at":"2026-02-25T09:00:00Z","by":"p-alnoor-gm","plan":[{"term":"2025S2","seats":12},{"term":"2026S1","seats":12},{"term":"2026S2","seats":12}]}]'::jsonb, 'p-alnoor-gm', '2026-02-25T09:00:00Z', 'p-alnoor-gm', '2026-09-22T09:00:00Z', false, true),
('pc-org-alnoor-2', 'org-alnoor', 'Al Noor Precision Engineering LLC (synthetic)', 'النور للهندسة الدقيقة (اصطناعية)', 'supplier', 'rdr-2025-1', 'quality', 'course_change', 'Quality inspection and NDT refresher', 'تحديث مهارات فحص الجودة والاختبارات غير الإتلافية', 'The in-house inspection course adds non-destructive testing practice and a records module aligned with the plant quality skills.', 'يضيف مقرر الفحص الداخلي تطبيقات الاختبارات غير الإتلافية ووحدة للسجلات متوافقة مع مهارات الجودة في المحطة.', array['sk-qa-01']::text[], 2, '[{"term":"2026S1","seats":20},{"term":"2026S2","seats":20}]'::jsonb, '[]'::jsonb, 'active', null, 'pending', null, null, null, 1, '[{"action":"create","version":1,"at":"2026-07-01T09:00:00Z","by":"p-alnoor-gm","plan":[{"term":"2026S1","seats":20},{"term":"2026S2","seats":20}]}]'::jsonb, 'p-alnoor-gm', '2026-07-01T09:00:00Z', 'p-alnoor-gm', '2026-07-01T09:00:00Z', false, true),
