('pc-org-gulfhydro-2', 'org-gulfhydro', 'Gulf Hydro-Valve Industries LLC (synthetic)', 'الخليج للصمامات الهيدروليكية (اصطناعية)', 'supplier', 'rdr-2025-1', 'safety', 'new_course', 'Engineering safety basics for supplier staff', 'أساسيات السلامة الهندسية لموظفي الموردين', 'A new course on safety classification, change control and reporting for supplier engineers working on plant components.', 'مقرر جديد حول تصنيف السلامة وضبط التغيير والإبلاغ لمهندسي الموردين العاملين على مكونات المحطة.', array['sk-ns-01','sk-ns-02']::text[], 1, '[{"term":"2026S2","seats":25}]'::jsonb, '[]'::jsonb, 'active', null, 'pending', null, null, null, 1, '[{"action":"create","version":1,"at":"2026-09-01T09:00:00Z","by":"p-gulfhydro-qa","plan":[{"term":"2026S2","seats":25}]}]'::jsonb, 'p-gulfhydro-qa', '2026-09-01T09:00:00Z', 'p-gulfhydro-qa', '2026-09-01T09:00:00Z', false, true),
